//! The macOS Dock icon, set from the app's own icon at startup.
//!
//! A packaged `.app` gets its icon from the bundle, but a development build is a bare executable
//! and macOS shows a generic icon for it. Setting the application icon here fixes both cases.

/// The same artwork as the bundle's icon (generated by `tauri icon`).
#[cfg(target_os = "macos")]
const ICON: &[u8] = include_bytes!("../icons/icon.icns");

/// Must run on the main thread (the `setup` hook does).
#[cfg(target_os = "macos")]
pub fn apply() {
    use objc2::AllocAnyThread;
    use objc2_app_kit::{NSApplication, NSImage};
    use objc2_foundation::{MainThreadMarker, NSData};

    let Some(mtm) = MainThreadMarker::new() else {
        eprintln!("Dock icon not set: not on the main thread");
        return;
    };
    let data = NSData::with_bytes(ICON);
    let Some(image) = NSImage::initWithData(NSImage::alloc(), &data) else {
        eprintln!("Dock icon not set: the icon could not be read");
        return;
    };
    unsafe { NSApplication::sharedApplication(mtm).setApplicationIconImage(Some(&image)) };
}

#[cfg(not(target_os = "macos"))]
pub fn apply() {}
